/* Staff Photos Asset Database - Auto-generated from FOTO/*.HEIC */
(function() {
  window.KUK_STAFF_PHOTOS = {
    "agheea": "data:image/jpeg;base64,",
    "andika": "data:image/jpeg;base64,",
    "anshory": "data:image/jpeg;base64,",
    "ari": "data:image/jpeg;base64,",
    "aria": "data:image/jpeg;base64,",
    "basith": "data:image/jpeg;base64,",
    "fariz": "data:image/jpeg;base64,",
    "lintang": "data:image/jpeg;base64,",
    "raju": "data:image/jpeg;base64,",
    "shuva": "data:image/jpeg;base64,",
    "zain": "data:image/jpeg;base64,",
  };

  window.getStaffPhoto = function(username) {
    if (!username) return null;
    const u = String(username).toLowerCase().trim();
    return window.KUK_STAFF_PHOTOS[u] || null;
  };

  // Auto-seed into localStorage if not already present
  try {
    for (const [user, dataUri] of Object.entries(window.KUK_STAFF_PHOTOS)) {
      const key = 'kuk_user_photo_' + user;
      if (!localStorage.getItem(key)) {
        localStorage.setItem(key, dataUri);
      }
    }
  } catch(e) {}
})();
